// Generated by retro + bun. Reports what the phone actually shows (screen
// size, fonts, errors, warnings) back to the sync server's terminal.
import Constants from 'expo-constants';
import { Component, useEffect, type ReactNode } from 'react';
import { PixelRatio, View, useWindowDimensions, type LayoutChangeEvent } from 'react-native';

const host = String(Constants.expoConfig?.hostUri ?? '').split(':')[0];
const url = host ? 'http://' + host + ':3333/report' : '';

export function report(kind: string, data: Record<string, unknown> = {}) {
  if (!url) return;
  fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ kind, ...data }) }).catch(() => {});
}

// Crashes and warnings anywhere in the app, reported once per app load.
const g = globalThis as unknown as { __mixReport?: boolean; ErrorUtils?: { getGlobalHandler(): (e: Error, fatal?: boolean) => void; setGlobalHandler(h: (e: Error, fatal?: boolean) => void): void } };
if (!g.__mixReport) {
  g.__mixReport = true;
  const prev = g.ErrorUtils?.getGlobalHandler();
  g.ErrorUtils?.setGlobalHandler((e, fatal) => {
    report('error', { message: String(e?.message ?? e), stack: String(e?.stack ?? '').split('\n').slice(1, 4).join(' | '), fatal: !!fatal });
    prev?.(e, fatal);
  });
  const warn = console.warn;
  console.warn = (...args: unknown[]) => { report('warn', { message: args.map(String).join(' ').slice(0, 300) }); warn(...args); };
}

class Boundary extends Component<{ screen: string; children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  componentDidCatch(e: Error) { report('render-error', { screen: this.props.screen, message: String(e?.message ?? e) }); }
  render() { return this.state.failed ? null : this.props.children; }
}

export function Reported({ screen, fontsReady, fontError, children }: { screen: string; fontsReady: boolean; fontError: Error | null; children: ReactNode }) {
  const win = useWindowDimensions();
  const w = Math.round(win.width), h = Math.round(win.height);
  useEffect(() => {
    report('screen', { screen, window: { w, h }, scale: PixelRatio.get(), fontScale: PixelRatio.getFontScale(), fontsReady, fontError: fontError ? String(fontError) : undefined });
  }, [screen, w, h, fontsReady, fontError]);
  const onLayout = (e: LayoutChangeEvent) => {
    const l = e.nativeEvent.layout;
    report('layout', { screen, root: { w: Math.round(l.width), h: Math.round(l.height) }, window: { w, h } });
  };
  return (
    <View style={{ flex: 1 }} onLayout={onLayout}>
      <Boundary screen={screen}>{children}</Boundary>
    </View>
  );
}
